## Other information
DTO used:
<details>
<summary>create-user.dto.ts</summary>

```typescript
import { ApiModelProperty, ApiModelPropertyOptional } from '@nestjs/swagger';
import {
  IsEmail,
  IsNotEmpty,
  IsOptional,
  ValidateNested,
} from 'class-validator';
import { UserAddressDto } from './user-address.dto';
import { UserPassportDto } from './user-passport.dto';
import { Type } from 'class-transformer';

export class CreateUserDto {
  @ApiModelProperty({ example: 'john.doe@gmail.com' })
  @IsNotEmpty()
  @IsEmail()
  email!: string;

  @ApiModelPropertyOptional({ type: UserPassportDto })
  @IsOptional()
  @ValidateNested()
  @Type(() => UserPassportDto)
  readonly passport?: UserPassportDto;

  @ApiModelPropertyOptional({ type: UserAddressDto })
  @IsOptional()
  @ValidateNested()
  @Type(() => UserAddressDto)
  readonly address?: UserAddressDto;
}
```
</details>

