<summary>user-passport.dto.ts</summary>

```typescript
import { ApiModelProperty, ApiModelPropertyOptional } from '@nestjs/swagger';
import { IsISO31661Alpha2, IsNotEmpty, IsString } from 'class-validator';
import { IsDateValid } from '@app/common/validator/is-date-valid.validator';

export class UserPassportDto {
  @ApiModelProperty({ example: 'John' })
  @IsNotEmpty()
  @IsString()
  readonly first_name!: string;

  @ApiModelProperty({ example: 'Doe' })
  @IsNotEmpty()
  @IsString()
  readonly last_name!: string;

  @ApiModelProperty({ example: '6625 21720' })
  @IsNotEmpty()
  @IsString()
  readonly passport_number!: string;

  @ApiModelProperty({ example: 'ES' })
  @IsNotEmpty()
  @IsISO31661Alpha2()
  readonly issuing_country_code!: string;

  @ApiModelPropertyOptional({ example: '2028-12-29' })
  @IsNotEmpty()
  @IsString()
  @IsDateValid()
  readonly expiration_date!: string;
}
```
</details>

