import { ApiModelProperty, ApiModelPropertyOptional } from '@nestjs/swagger';
import { IsNotEmpty, IsOptional, IsString } from 'class-validator';
import { IsNonEuCountryCodeValid } from '@app/countries-common';

export class UserAddressDto {
  @ApiModelProperty({ example: 'Las Palmas de Gran Canaria' })
  @IsNotEmpty()
  @IsString()
  readonly city!: string;

  @ApiModelProperty({ example: 'IC' })
  @IsNotEmpty()
  @IsNonEuCountryCodeValid()
  readonly country_code!: string;

  @ApiModelProperty({ example: 'Av. Juan Carlos I, 20' })
  @IsNotEmpty()
  @IsString()
  readonly line!: string;

  @ApiModelPropertyOptional({ example: null })
  @IsOptional()
  @IsNotEmpty()
  @IsString()
  readonly line_additional?: string;

  @ApiModelProperty({ example: '35019' })
  @IsNotEmpty()
  @IsString()
  readonly postcode!: string;
}
```
